"""JSON batch entry point of the eMicro CPU control plane.

Reads one UTF-8 JSON request from standard input and writes one JSON response
to standard output.  Whole-request envelope failures are rejected before any
job is replayed; structurally invalid jobs are rejected without replay.
"""

import json
import math
import os
import re
import select
import sys

_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.insert(0, _HERE)

from syntax import parse_policy, PolicyError
from ebpf.helper import Agent

U32 = 4294967295
INPUT_CAP = 24 * 1024 * 1024
MAX_JOBS = 4
MAX_EVENTS = 200000
MAX_STAGES = 16
POLICY_CAP = 8 * 1024 * 1024
ATOM_CAP = 32768
PATH_CAP = 65536
NESTING_CAP = 64

NAME = re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}\Z')
LIMIT_MAX = {'images': 16, 'cells': 262144, 'units': 1024, 'contexts': 32768,
             'connections': 4096, 'packets': 32768, 'files': 8192}

K_POS, K_UNIT, K_PAIR, K_NAME, K_TEXT, K_WIRE = range(6)
SCHEMA = {
    'stage': {'epoch': K_POS, 'policy': K_TEXT},
    'commit': {'epoch': K_POS},
    'retire': {'epoch': K_POS},
    'spawn': {'unit': K_UNIT, 'service': K_NAME},
    'clone': {'parent': K_UNIT, 'child': K_UNIT},
    'exit': {'unit': K_UNIT},
    'begin': {'unit': K_UNIT, 'rid': K_POS},
    'finish': {'unit': K_UNIT, 'rid': K_POS},
    'open': {'connection': K_PAIR},
    'close': {'connection': K_PAIR},
    'send': {'unit': K_UNIT, 'rid': K_POS, 'connection': K_PAIR,
             'stream': K_POS, 'destination': K_NAME},
    'recv': {'unit': K_UNIT, 'rid': K_POS, 'connection': K_PAIR,
             'stream': K_POS, 'wire': K_WIRE},
    'store': {'unit': K_UNIT, 'rid': K_POS, 'file': K_PAIR},
    'load': {'unit': K_UNIT, 'rid': K_POS, 'file': K_PAIR},
    'unlink': {'file': K_PAIR},
    'inspect': {},
}
SCHEMA_SIZE = {op: len(fields) + 1 for op, fields in SCHEMA.items()}


class Invalid(Exception):
    """Whole-request rejection."""


# ---------------------------------------------------------------- input ----
def read_input(limit):
    """Read standard input, tolerating a non-blocking underlying descriptor."""
    try:
        handle = sys.stdin.buffer
    except AttributeError:
        handle = sys.stdin
    try:
        fileno = handle.fileno()
    except Exception:
        fileno = None
    if fileno is None:
        return _read_stream(handle, limit)
    chunks = []
    total = 0
    while total < limit:
        try:
            block = os.read(fileno, 1 << 20)
        except BlockingIOError:
            select.select([fileno], [], [])
            continue
        except InterruptedError:
            continue
        except OSError:
            return _read_stream(handle, limit)
        if not block:
            break
        chunks.append(block)
        total += len(block)
    return b''.join(chunks)


def _read_stream(handle, limit):
    try:
        data = handle.read(limit)
    except Exception:
        return b''
    if data is None:
        return b''
    if isinstance(data, str):
        data = data.encode('utf-8', 'surrogatepass')
    return data


# ------------------------------------------------------------- validation --
def _unique(pairs):
    seen = {}
    for key, value in pairs:
        if key in seen:
            raise Invalid('duplicate key')
        seen[key] = value
    return seen


def _constant(token):
    raise Invalid('nonfinite constant')


def _number(token):
    value = float(token)
    if not math.isfinite(value):
        raise Invalid('nonfinite number')
    return value


def _integer(value, low, high):
    return type(value) is int and low <= value <= high


def _typed(value, kind):
    if kind == K_POS:
        return _integer(value, 1, U32)
    if kind == K_UNIT:
        return (type(value) is list and len(value) == 3
                and _integer(value[0], 0, U32)
                and _integer(value[1], 1, U32)
                and _integer(value[2], 1, U32))
    if kind == K_PAIR:
        return (type(value) is list and len(value) == 2
                and _integer(value[0], 1, U32)
                and _integer(value[1], 1, U32))
    if kind == K_NAME:
        return type(value) is str and value.isascii() and NAME.match(value) is not None
    if kind == K_TEXT:
        if type(value) is not str:
            return False
        if value.isascii():
            return True
        try:
            value.encode('utf-8')
        except UnicodeEncodeError:
            return False
        return True
    if kind == K_WIRE:
        return value is None or (type(value) is str and len(value) <= 96)
    return False


def _bounded(obj, level):
    """True when no container nesting exceeds the declared depth."""
    stack = [(obj, level)]
    pop = stack.pop
    push = stack.append
    while stack:
        item, depth = pop()
        if depth > NESTING_CAP:
            return False
        kind = type(item)
        if kind is dict:
            deeper = depth + 1
            for value in item.values():
                if type(value) is dict or type(value) is list:
                    push((value, deeper))
        elif kind is list:
            deeper = depth + 1
            for value in item:
                if type(value) is dict or type(value) is list:
                    push((value, deeper))
    return True


def validate_job(job, cache):
    """Return ``(events, policy_bytes, stages, atoms, paths)`` or ``None``."""
    if type(job) is not dict or len(job) != 3:
        return None
    services = job.get('services')
    limits = job.get('limits')
    events = job.get('events')
    if services is None or limits is None or events is None:
        return None
    if type(services) is not list or not 1 <= len(services) <= 16:
        return None
    names = set()
    labels = set()
    for service in services:
        if type(service) is not dict or len(service) != 2:
            return None
        name = service.get('name')
        label = service.get('label')
        if (type(name) is not str or not name.isascii()
                or NAME.match(name) is None):
            return None
        if not _integer(label, 1, U32 - 1):
            return None
        if name in names or label in labels:
            return None
        names.add(name)
        labels.add(label)
    if type(limits) is not dict or len(limits) != len(LIMIT_MAX):
        return None
    for key, value in limits.items():
        ceiling = LIMIT_MAX.get(key)
        if ceiling is None or not _integer(value, 1, ceiling):
            return None
    if type(events) is not list or len(events) > MAX_EVENTS:
        return None
    policy_bytes = 0
    stages = 0
    atoms = 0
    paths = 0
    for event in events:
        if type(event) is not dict:
            return None
        op = event.get('op')
        if type(op) is not str:
            return None
        fields = SCHEMA.get(op)
        if fields is None:
            return None
        if len(event) != SCHEMA_SIZE[op]:
            return None
        for key in fields:
            if key not in event:
                return None
        for key, kind in fields.items():
            if not _typed(event[key], kind):
                return None
        if op == 'stage':
            policy = event['policy']
            policy_bytes += len(policy) if policy.isascii() else len(
                policy.encode('utf-8'))
            stages += 1
            counted = cache.get(policy, 0)
            if counted == 0:
                try:
                    counted = parse_policy(policy)
                except PolicyError:
                    counted = None
                cache[policy] = counted
            if counted is not None:
                atoms += counted[1]
                paths += counted[2]
    return len(events), policy_bytes, stages, atoms, paths


# ---------------------------------------------------------------- output ---
class Writer(object):
    """Bounded pipe friendly byte writer with explicit flushing."""

    __slots__ = ('fileno', 'pending')

    def __init__(self):
        try:
            self.fileno = sys.stdout.fileno()
        except Exception:
            self.fileno = 1
        self.pending = bytearray()

    def write(self, text):
        buffer = self.pending
        buffer += text.encode('utf-8')
        if len(buffer) >= 1 << 16:
            self.flush()

    def flush(self):
        buffer = self.pending
        if not buffer:
            return
        view = memoryview(buffer)
        size = len(buffer)
        done = 0
        fileno = self.fileno
        while done < size:
            try:
                done += os.write(fileno, view[done:])
            except BlockingIOError:
                select.select([], [fileno], [])
            except InterruptedError:
                continue
        del buffer[:]


# ----------------------------------------------------------------- solve ---
def solve(data):
    try:
        if len(data) > INPUT_CAP:
            return {'error': 'invalid'}
        text = data.decode('utf-8')
    except Exception:
        return {'error': 'invalid'}
    if text.startswith('\ufeff'):
        return {'error': 'invalid'}
    try:
        request = json.loads(text, object_pairs_hook=_unique,
                             parse_constant=_constant, parse_float=_number)
    except Exception:
        return {'error': 'invalid'}
    text = None
    data = None
    try:
        if (type(request) is not dict or len(request) != 1
                or type(request.get('jobs')) is not list
                or len(request['jobs']) > MAX_JOBS):
            return {'error': 'invalid'}
        if not _bounded(request, 1):
            return {'error': 'invalid'}
    except Exception:
        return {'error': 'invalid'}
    jobs = request['jobs']
    cache = {}
    total_events = 0
    total_policy = 0
    total_stages = 0
    total_atoms = 0
    total_paths = 0
    valid = []
    for job in jobs:
        report = validate_job(job, cache)
        if report is None:
            valid.append(False)
            continue
        valid.append(True)
        total_events += report[0]
        total_policy += report[1]
        total_stages += report[2]
        total_atoms += report[3]
        total_paths += report[4]
    if (total_events > MAX_EVENTS or total_policy > POLICY_CAP
            or total_stages > MAX_STAGES or total_atoms > ATOM_CAP
            or total_paths > PATH_CAP):
        return {'error': 'invalid'}
    del request
    writer = Writer()
    writer.write('{"results":[')
    separator = ''
    for job, usable in zip(jobs, valid):
        writer.write(separator)
        separator = ','
        if not usable:
            writer.write('{"error":"invalid"}')
            continue
        agent = Agent(job['services'], job['limits'], cache)
        writer.write('{"events":[')
        first = ''
        for event in job['events']:
            writer.write(first)
            first = ','
            writer.write(json.dumps(agent.event(event), separators=(',', ':')))
        writer.write(']}')
    writer.write(']}')
    writer.flush()
    return None


def main():
    try:
        data = read_input(INPUT_CAP + 1)
        result = solve(data)
    except Exception:
        result = {'error': 'invalid'}
    if result is not None:
        sys.stdout.write(json.dumps(result, separators=(',', ':')))
        sys.stdout.write('\n')
        try:
            sys.stdout.flush()
        except Exception:
            pass


if __name__ == '__main__':
    main()
PYEOF
